Method.Source:
/// <summary>
/// DebuC 06.02.23
/// </summary>
/// <param name = "_NDX_CharacteristicID">NDX_CharacteristicID</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDX_MaterialCharacteristic</returns>
static NDX_MaterialCharacteristic find(NDX_CharacteristicID  _NDX_CharacteristicID, boolean _forUpdate = false)
{
    NDX_MaterialCharacteristic  nDX_MaterialCharacteristic;
    ;
    nDX_MaterialCharacteristic.selectForUpdate(_forUpdate);

    if (_NDX_CharacteristicID)
    {
        select firstonly nDX_MaterialCharacteristic
            where nDX_MaterialCharacteristic.NDX_CharacteristicID  == _NDX_CharacteristicID;
    }

    return NDX_MaterialCharacteristic;
}

/// <summary>
/// DebuC 06.02.23
/// </summary>
/// <param name = "_formControl">FormControl</param>
/// <param name = "_filterStr">str</param>
[SuppressBPWarning('BPParameterNotUsed','The paraneter "_filterStr" is not used')]
static void lookupSubstituteMaterialID(FormControl _formControl, str _filterStr)
{
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource;
    SysTableLookup          sysTableLookup;

    NDX_MaterialGroupStatusTable lNDX_MaterialGroupStatusTable;
    ;

    sysTableLookup = SysTableLookup::newParameters(tableNum(NDX_MaterialCharacteristic), _formControl);
    queryBuildDataSource = query.addDataSource(tableNum(NDX_MaterialCharacteristic));

    while select lNDX_MaterialGroupStatusTable
    where !lNDX_MaterialGroupStatusTable.Locked
    {
        queryBuildDataSource.addRange(fieldNum(NDX_MaterialCharacteristic, NDX_MaterialGroupStatus)).value(QueryValue(lNDX_MaterialGroupStatusTable.MaterialGroupStatus));
    }

    sysTableLookup.addLookupField(fieldNum(NDX_MaterialCharacteristic, NDX_CharacteristicID), true);
    sysTableLookup.addLookupField(fieldNum(NDX_MaterialCharacteristic, NDX_CharacteristicDescription));

    sysTableLookup.parmUseLookupValue(false);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// DebuC 06.02.23
/// </summary>
/// <param name = "_formControl">FormControl</param>
/// <param name = "_filterStr">str</param>
[SuppressBPWarning('BPParameterNotUsed','The paraneter "_filterStr" is not used')]
static void lookupStatus(FormControl _formControl, str _filterStr)
{
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource;
    SysTableLookup          sysTableLookup;

    NDX_MaterialGroupStatusTable lNDX_MaterialGroupStatusTable;
    ;

    sysTableLookup = SysTableLookup::newParameters(tableNum(NDX_MaterialGroupStatusTable), _formControl);
    queryBuildDataSource = query.addDataSource(tableNum(NDX_MaterialGroupStatusTable));

    while select lNDX_MaterialGroupStatusTable
    where !lNDX_MaterialGroupStatusTable.Locked
    {
        queryBuildDataSource.addRange(fieldNum(NDX_MaterialGroupStatusTable, MaterialGroupStatus)).value(QueryValue(lNDX_MaterialGroupStatusTable.MaterialGroupStatus));
    }

    sysTableLookup.addLookupField(fieldNum(NDX_MaterialGroupStatusTable, MaterialGroupStatus), true);
    sysTableLookup.addLookupField(fieldNum(NDX_MaterialGroupStatusTable, Description));

    sysTableLookup.parmUseLookupValue(false);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
